            return FlashInferBackend.get_dtype_for_flashinfer(cache_dtype)
        return self.model_config.dtype
    if cache_dtype.startswith("nvfp4"):
        return FlashInferBackend.get_dtype_for_flashinfer("fp8_e4m3")

